@resultBuilder
struct HeaderBuilder {
    static func buildBlock(_ lines: String...) -> String {
        return lines.filter { !$0.isEmpty }.joined(separator: ": ")
    }

    static func buildOptional(_ line: String?) -> String {
        return line ?? ""
    }
}

func makeHeader(@HeaderBuilder content: () -> String) -> String {
    return content()
}

let isVip = true
let title = makeHeader {
    "Header"
    if isVip {
        "VIP"
    }
}
