@resultBuilder
struct BranchBuilder {
    static func buildBlock(_ items: String...) -> String {
        return items.joined(separator: ": ")
    }

    static func buildEither(first item: String) -> String {
        return item
    }

    static func buildEither(second item: String) -> String {
        return item
    }
}

func makeSelection(choice: Int, @BranchBuilder content: () -> String) -> String {
    return content()
}

let choice = 2
let message = makeSelection(choice: choice) {
    "Option"
    if choice == 1 {
        "A"
    } else {
        "B"
    }
}
print(message)

